      l10n.adminText('user.warehouse_worker_subtitle'),
    _AdminUserCreateKind.customer => l10n.adminText('user.customer_subtitle'),
    _AdminUserCreateKind.supplier => l10n.adminText('user.supplier_subtitle'),
